记录数据库课程第一次上机作业
Q1 1CREATE TABLE dp ( 2 dp_id VARCHAR(20) not null PRIMARY KEY, -- 部门编号 3 dp_name VARCHAR(100) NOT NULL, -- 部门名 4 floor INT -- 楼层 5); 6 7-- 2) 员工表 8CREATE TABLE employee ( 9 em_id VARCHAR(20) not null PRIMARY KEY, -- 员工编号 10 em_name VARCHAR(50) NOT NULL, -- 员工姓名 11 em_salary NUMERIC(10,2) NOT null, -- 员工薪资 12 absence_days	INT not null DEFAULT 0, -- 员工缺勤天数 13 birth_day	DATE, -- 员工生日 14 if_married	BOOL, -- 员工婚姻情况 15 dp_id	VARCHAR(20) not null, -- 员工所属部门 16 CONSTRAINT chk_em_salary check (em_salary &gt;= 2000 ) 17); 18 19-- 加外键 20ALTER TABLE employee 21 ADD CONSTRAINT fk_dp_employee 22 FOREIGN KEY (dp_id) REFERENCES dp(dp_id); Q2 1-- dp 表数据 2INSERT INTO dp (dp_id, dp_name, floor) VALUES 3(&#39;DP007&#39;, &#39;第一部门&#39;, 12), 4(&#39;DP996&#39;, &#39;第二部门&#39;, 8), 5(&#39;DP110&#39;, &#39;第四部门&#39;, 15); 6 7-- employee 表数据 8INSERT INTO employee (em_id, em_name, em_salary, absence_days, birth_day, if_married, dp_id) VALUES 9(&#39;412502&#39;, &#39;Dong Zi&#39;, &#39;6000&#39;, &#39;300&#39;, &#39;2009-09-25&#39;, &#39;0&#39;, &#39;DP007&#39;), 10(&#39;112233&#39;, &#39;Xiao Zhang&#39;, &#39;2500&#39;, &#39;3&#39;, &#39;2000-03-24&#39;, &#39;0&#39;, &#39;DP996&#39;), 11(&#39;904862&#39;, &#39;Old Shi&#39;, &#39;3000&#39;, &#39;0&#39;, &#39;1996-01-26&#39;, &#39;1&#39;, &#39;DP110&#39;), 12(&#39;201001&#39;, &#39;Li Wei&#39;, &#39;3200&#39;, &#39;0&#39;, &#39;1995-07-12&#39;, &#39;1&#39;, &#39;DP007&#39;), 13(&#39;201002&#39;, &#39;Wang Fang&#39;, &#39;2800&#39;, &#39;2&#39;, &#39;1998-11-03&#39;, &#39;0&#39;, &#39;DP007&#39;), 14(&#39;305678&#39;, &#39;Chen Hao&#39;, &#39;4500&#39;, &#39;5&#39;, &#39;1992-04-18&#39;, &#39;1&#39;, &#39;DP996&#39;), 15(&#39;408888&#39;, &#39;Liu Yang&#39;, &#39;2100&#39;, &#39;0&#39;, &#39;2001-06-30&#39;, &#39;0&#39;, &#39;DP996&#39;), 16(&#39;556677&#39;, &#39;Zhao Min&#39;, &#39;5500&#39;, &#39;1&#39;, &#39;1990-02-14&#39;, &#39;1&#39;, &#39;DP110&#39;), 17(&#39;667788&#39;, &#39;Sun Lei&#39;, &#39;3800&#39;, &#39;4&#39;, &#39;1997-09-09&#39;, &#39;0&#39;, &#39;DP110&#39;), 18(&#39;778899&#39;, &#39;Zhou Jing&#39;, &#39;2600&#39;, &#39;0&#39;, &#39;1999-12-01&#39;, &#39;0&#39;, &#39;DP996&#39;); 不能删除，因为删除的数据中有数据作为其他表的外键被引用
Q3-Q13 1-- Q3 2SELECT em_salary, absence_days 3FROM employee; 4 5-- Q4 6SELECT COUNT(*) AS employee_count 7FROM employee; 8 9-- Q5 10SELECT AVG(em_salary) AS avg_salary 11FROM employee; 12 13-- Q6 14SELECT dp_id, 15 MAX(em_salary) AS max_salary, 16 MIN(em_salary) AS min_salary 17FROM employee 18WHERE dp_id = &#39;DP007&#39; 19GROUP BY dp_id; 20 21-- Q7 22SELECT em_name 23FROM employee 24WHERE absence_days &gt; 3; 25 26-- Q9 27SELECT UPPER(em_name) AS em_name_upper 28FROM employee; 29 30-- Q10（openGauss） 31SELECT em_id, 32 em_name, 33 birth_day, 34 TO_CHAR(birth_day, &#39;YYYY/MM/DD&#39;) AS birth_fmt_slash, 35 TO_CHAR(birth_day, &#39;YYYYMMDD&#39;) AS birth_fmt_compact 36FROM employee; 37 38-- Q11（openGauss）选定员工：412502 39SELECT em_name, 40 SUBSTR(em_name, 1, POSITION(&#39; &#39; IN em_name) - 1) AS part1, 41 SUBSTR(em_name, POSITION(&#39; &#39; IN em_name) + 1) AS part2 42FROM employee 43WHERE em_id = &#39;412502&#39;; 44 45SELECT AGE(e1.birth_day, e2.birth_day) AS age_interval 46FROM employee e1, employee e2 47WHERE e1.em_id = &#39;112233&#39; AND e2.em_id = &#39;904862&#39;; 48 49-- Q13（openGauss） 50SELECT em_id, em_name, birth_day 51FROM employee 52WHERE birth_day &gt; TO_DATE(&#39;2000-01-01&#39;, &#39;YYYY-MM-DD&#39;);
